import{X as e,Z as t,t as n,ut as r}from"./chunks/framework.es-12sf8.js";var i=JSON.parse(`{"title":"Module Management Page","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/module-management-page.md","filePath":"en/deep-dive/module-management-page.md","lastUpdated":1788278373000}`),a={name:`deep-dive/module-management-page.md`};function o(n,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[t(`<h1 id="module-management-page" tabindex="-1">Module Management Page <a class="header-anchor" href="#module-management-page" aria-label="Permalink to “Module Management Page”">​</a></h1><p>Sync Engine uses a native Obsidian settings page to manage executable modules from configured sources. Open it from <a href="./../usage/settings#module-management">Module management</a>.</p><h2 id="page-layout" tabindex="-1">Page Layout <a class="header-anchor" href="#page-layout" aria-label="Permalink to “Page Layout”">​</a></h2><p><code>ModuleManagement</code> extends Obsidian&#39;s <code>SettingPage</code>. Its page contains:</p><ul><li>a full-width search field;</li><li>an icon button that opens a menu with the <strong>Show installed only</strong> toggle and <strong>Install module from file</strong>;</li><li>a Solid.js module-card list.</li></ul><p>Module source URLs are edited separately on <strong>Settings &gt; Sync Engine &gt; Development &gt; Module sources</strong>. Returning to Module management creates a new source snapshot and refreshes the catalog.</p><p>The search field uses Obsidian&#39;s <code>SearchComponent</code>. An empty query sorts modules alphabetically. A non-empty query uses <code>prepareFuzzySearch()</code> against module names and descriptions, then sorts by match score and name.</p><p><strong>Install module from file</strong> opens a file picker that only accepts <code>.js</code> files; other extensions are rejected with a notice. The chosen file opens the module editor with metadata prefilled from the file&#39;s magic bytes, see <a href="./extensibility#install-from-file">extensibility: install from file</a>.</p><h2 id="module-cards" tabindex="-1">Module Cards <a class="header-anchor" href="#module-cards" aria-label="Permalink to “Module Cards”">​</a></h2><p>Each card displays the module icon, name, version, source status, description, and available actions:</p><ul><li><strong>Download</strong> installs a module that is not installed or has a newer advertised version.</li><li><strong>README</strong> opens the module&#39;s README page when its metadata provides one.</li><li><strong>Edit</strong> opens the module metadata and integrity settings.</li><li><strong>Delete</strong> removes the installed module and its stored metadata.</li><li><strong>Enable</strong> stores <code>enabled: true</code> and loads the module.</li><li><strong>Disable</strong> unloads the module and stores <code>enabled: false</code>.</li></ul><p>Actions are disabled while another action for the same module is running. Running actions display a progress icon. Module cards are merged by module ID, with installed metadata taking precedence over source metadata.</p><h2 id="source-and-compatibility-state" tabindex="-1">Source And Compatibility State <a class="header-anchor" href="#source-and-compatibility-state" aria-label="Permalink to “Source And Compatibility State”">​</a></h2><p><code>fetchSources()</code> reads every configured source. Source responses are cached for automatic update checks and can be forced to refresh for manual operations. Duplicate IDs within a source are ignored.</p><p>If a source entry declares a <code>minPluginVersion</code> newer than the running plugin, the catalog marks the plugin as outdated. Update Sync Engine before installing modules that require the newer version.</p><p>Newly downloaded modules are disabled by default. Automatic updates only apply to already-installed modules whose recorded source URL matches the advertised source URL.</p>`,16)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};